def sl(v,d=1):return '/'.join(f(x,d) for x in v)
def para(t,prefix,new):
    anchor='' if prefix=='The application compares partial railway fare' else r'(?m)^'
    t,n=re.subn(anchor+re.escape(prefix)+r'[^\n]*',lambda _:new,t);assert n==1,(prefix,n);return t
def grouping(t):
    def sub(m):
        s=m[0]
        if s=='12306' or ('.' not in s and 1900<=abs(int(s))<=2100):return s
        return format(float(s),',.'+str(len(s.split('.')[1]) if '.' in s else 0)+'f')
    return re.sub(r'(?<![\w.,])(-?\d{4,}(?:\.\d+)?)(?![\w.])',sub,t)
