    path=P/'tables/v3_experiments.tex';t=path.read_text(encoding='utf-8');t=t.replace(mark,panel('D. Commercial P3: profit gain above welfare change (CNY k/day)','llrrrrrr',['Case','Cap','-0.60','-0.80','-0.85','-0.90','-0.95','-1.00'],rr)+mark).replace('Three elasticity anchors crossed with three fare caps','Six elasticity anchors crossed with three fare caps')
