    for r in R['strict']:rr+=row([r['case_id']+(r'$^{*}$' if r['certificate'] else ''),f(r['strict_fare'],3),f(100*r['traveler_surplus_recovery']),f(r['profit_gain']/1000),f(r['welfare_gain']/1000),f(100*r['benchmark_fraction'])])
