    for r in R['tradeoffs']:rr+=row([r['case_id'],r['lever'].replace('Central cap ','Cap ').replace('Tighter cap ','Cap ').replace('Strict floor ','Floor '),f(r['profit_gain']/1000),f(100*r['profit_retained']),f(r['U_change']/1000),f(r['W_change']/1000),f(r['fare'],3)])
    t=t.replace(mark,panel('D. Central cap versus strict floor: common commercial benchmark','llrrrrr',['Case','Lever',r'$\Delta\Pi$ (k)',r'Profit kept (\%)',r'$\Delta U$ (k)',r'$\Delta W$ (k)','Mean fare'],rr)+mark).replace('not a social resource cost.',r'not a social resource cost. Starred strict-floor HN/WC profit designs are certified with hard retention and finance; JX is a coordinated multi-start witness. W benchmark uses the reference P3 welfare design in Table~\ref{tab:baseline_policy_values}. Profit kept in D is relative to the cap-1.20, floor-0.95 profit gain. Broad fare restraint benefits travelers beyond the restored L trips.');path.write_text(t,encoding='utf-8')
