    car=B.CAR['records'];counts=[ci+' '+sl([sum(r['changed'] for r in car if r['case_id']==ci and r['intensity']==x) for x in [0.,.35]],0) for ci in CIS];t=re.sub(r'Among four scenarios at each intensity,.*?The largest carbon correction is',lambda _: 'Changed-design counts among four carbon scenarios at road intensities 0/0.35 are '+', '.join(counts)+'. The largest carbon correction is',t)
    start=t.index('The three elasticity anchors -0.60');end=t.index('The tornado compares',start)
